import {
  HTMLAttributes,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'preact/compat';
import { useId } from 'preact/hooks';
import { Container, classes } from '@adobe-commerce/elsie/lib';
import {
  Button,
  ContentGrid,
  Image,
  InLineAlert,
  Modal,
  ProductItemCard,
  ProgressSpinner,
} from '@adobe-commerce/elsie/components';
import { useText } from '@adobe-commerce/elsie/i18n';
import { events } from '@adobe-commerce/event-bus';
import type {
  AvailableFreeGiftRule,
  CartModel,
  FreeGiftBundleItem,
  FreeGiftProduct,
} from '@/cart/data/models';
import { selectFreeGiftForCart } from '@/cart/api/selectFreeGiftForCart/selectFreeGiftForCart';
import { getAvailableFreeGiftsForCart } from '@/cart/api/getAvailableFreeGiftsForCart/getAvailableFreeGiftsForCart';
import { FreeGiftSelectionLoader } from '@/cart/containers/FreeGiftSelection/FreeGiftSelectionLoader';
import '@/cart/containers/FreeGiftSelection/FreeGiftSelection.css';

export interface FreeGiftSelectionProps extends HTMLAttributes<HTMLDivElement> {
  /** Shows the trigger button when pending free gifts are available. */
  showTrigger?: boolean;
  /**
   * Optional cart model override. Used both by callers that already hold the cart
   * (CartSummaryTable/List/Grid pass their live model here) and by isolated
   * Storybook/test usage.
   */
  cartData?: CartModel | null;
}

function toCartModel(payload: unknown): CartModel | null {
  if (payload == null) return null;
  if (typeof payload !== 'object') return null;
  const candidate = payload as CartModel & { type?: string };
  if (candidate.type && candidate.type !== 'cart') return null;
  return candidate;
}

function pickKey(ruleId: number, sku: string) {
  return `${ruleId}|${sku}`;
}

function bundleRowSortPosition(row: FreeGiftBundleItem): number {
  return row.position ?? 0;
}

function buildConfigurableUids(
  product: FreeGiftProduct,
  picks: Record<string, string>
): string[] {
  /* istanbul ignore next -- only called when configurableOptions.length > 0 */
  if (!product.configurableOptions?.length) return [];

  return product.configurableOptions
    .map((co) => picks[co.attributeUid])
    .filter(Boolean) as string[];
}

function getDefaultConfigPicks(product: FreeGiftProduct): Record<string, string> {
  if (!product.configurableOptions?.length) return {};

  return product.configurableOptions.reduce(
    (acc, option) => {
      const firstValueUid = option.values?.[0]?.uid;
      if (firstValueUid) {
        acc[option.attributeUid] = firstValueUid;
      }
      return acc;
    },
    {} as Record<string, string>
  );
}

function getDefaultBundlePicks(product: FreeGiftProduct): Record<string, string> {
  if (!product.bundleItems?.length) return {};

  return product.bundleItems.reduce(
    (acc: Record<string, string>, row: FreeGiftBundleItem) => {
      const defaultValue =
        row.values.find((v) => v.isDefault) ?? row.values[0];
      if (defaultValue?.uid) {
        acc[row.uid] = defaultValue.uid;
      }
      return acc;
    },
    {} as Record<string, string>
  );
}

function getDefaultOptionPicks(product: FreeGiftProduct): Record<string, string> {
  return {
    ...getDefaultConfigPicks(product),
    ...getDefaultBundlePicks(product),
  };
}

function buildBundleSelectedOptionUids(
  product: FreeGiftProduct,
  picks: Record<string, string>
): string[] {
  /* istanbul ignore next -- only called when bundleItems.length > 0 */
  if (!product.bundleItems?.length) return [];

  const sorted = [...product.bundleItems].sort(
    (a, b) => bundleRowSortPosition(a) - bundleRowSortPosition(b)
  );
  const rowsWithChoices = sorted.filter((row) => row.values.length > 0);

  return rowsWithChoices
    .map((row) => picks[row.uid])
    .filter(Boolean) as string[];
}

function productNeedsOptionPicks(product: FreeGiftProduct): boolean {
  return Boolean(
    product.configurableOptions?.length || product.bundleItems?.length
  );
}

function freeGiftRulesFingerprint(rules: AvailableFreeGiftRule[]): string {
  return JSON.stringify(
    rules.map((r) => ({
      ruleId: r.ruleId,
      skus: r.availableSkus,
      products: r.products.map((p) => p.sku),
    }))
  );
}

export const FreeGiftSelection: Container<FreeGiftSelectionProps> = ({
  showTrigger = true,
  cartData,
  ...rest
}: FreeGiftSelectionProps) => {
  const openTriggerHintId = useId();
  const dictionary = useText({
    title: 'Cart.FreeGiftSelection.title',
    empty: 'Cart.FreeGiftSelection.empty',
    error: 'Cart.FreeGiftSelection.error',
    ariaModal: 'Cart.FreeGiftSelection.ariaModal',
    openTrigger: 'Cart.FreeGiftSelection.openTrigger',
    openTriggerHint: 'Cart.FreeGiftSelection.openTriggerHint',
    addedMessagePrefix: 'Cart.FreeGiftSelection.addedMessagePrefix',
    chooseOption: 'Cart.FreeGiftSelection.chooseOption',
    configureRequired: 'Cart.FreeGiftSelection.configureRequired',
    ruleLabelFallback: 'Cart.FreeGiftSelection.ruleLabelFallback',
    selectProduct: 'Cart.FreeGiftSelection.selectProduct',
    addToCart: 'Cart.FreeGiftSelection.addToCart',
  });

  const [cart, setCart] = useState<CartModel | null>(null);
  const [open, setOpen] = useState(false);
  /** Which card is calling the API: `${ruleId}|${sku}` */
  const [submittingKey, setSubmittingKey] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  /** Which configurable / bundle card has options expanded: `${ruleId}|${sku}` */
  const [expandedPickKey, setExpandedPickKey] = useState<string | null>(null);
  const [configPicks, setConfigPicks] = useState<
    Record<string, Record<string, string>>
  >({});

  const errorAlertRef = useRef<HTMLDivElement | null>(null);
  const hasPopupOpenedRef = useRef(false);
  const handleOpenRef = useRef<
    ((options?: { suppressEmptyError?: boolean }) => void) | null
  >(null);
  const handleCloseRef = useRef<(() => void) | null>(null);

  const rules = useMemo(() => cart?.availableFreeGifts ?? [], [cart?.availableFreeGifts]);
  const rulesWithProducts = useMemo(
    () => rules.filter((rule) => rule.products?.length),
    [rules]
  );
  const rulesFingerprint = useMemo(() => freeGiftRulesFingerprint(rules), [rules]);

  useEffect(() => {
    if (cartData !== undefined) {
      setCart(cartData);
      return;
    }

    const subs = [
      events.on('cart/data', (c) => setCart(toCartModel(c)), { eager: true }),
      events.on('cart/updated', (c) => setCart(toCartModel(c)), { eager: true }),
      events.on('cart/initialized', (c) => setCart(toCartModel(c)), { eager: true }),
      events.on('checkout/initialized', (c) => setCart(toCartModel(c)), {
        eager: true,
      }),
      events.on('checkout/updated', (c) => setCart(toCartModel(c)), {
        eager: true,
      }),
    ];
    return () => {
      subs.forEach((s) => s?.off());
    };
  }, [cartData]);

  useEffect(() => {
    if (!cart?.hasAvailableFreeGifts) {
      hasPopupOpenedRef.current = false;
      setOpen(false);
      setError(null);
    }
  }, [cart?.hasAvailableFreeGifts, cart?.id]);

  const fetchingFreeGiftsRef = useRef(false);

  /**
   * `available_free_gifts` (products, configurable options, bundle items) is heavy and
   * no longer part of CART_FRAGMENT, so it's fetched lazily here only when the cheap
   * `has_available_free_gifts` flag says there's something to show. `cartData` is not
   * test/Storybook-only — CartSummaryTable/List/Grid pass the live cart through it too —
   * so this must still run in that case; callers that already supply populated
   * `availableFreeGifts` simply skip the fetch via the length check below.
   */
  useEffect(() => {
    if (!cart?.id || !cart?.hasAvailableFreeGifts) return;
    if (cart.availableFreeGifts?.length) return;
    if (fetchingFreeGiftsRef.current) return;

    const cartId = cart.id;
    fetchingFreeGiftsRef.current = true;
    getAvailableFreeGiftsForCart()
      .then((availableFreeGifts) => {
        setCart((prev) =>
          prev && prev.id === cartId ? { ...prev, availableFreeGifts } : prev
        );
      })
      .catch(() => {
        setError('error');
      })
      .finally(() => {
        fetchingFreeGiftsRef.current = false;
      });
  }, [cart?.id, cart?.hasAvailableFreeGifts, cart?.availableFreeGifts]);

  useEffect(() => {
    if (!expandedPickKey) return;
    const stillValid = rules.some((r) =>
      r.products.some((p) => pickKey(r.ruleId, p.sku) === expandedPickKey)
    );
    if (!stillValid) setExpandedPickKey(null);
  }, [rules, rulesFingerprint, expandedPickKey]);

  const setPick = useCallback(
    (
      ruleId: number,
      sku: string,
      optionGroupKey: string,
      valueUid: string
    ) => {
      const key = pickKey(ruleId, sku);
      setConfigPicks((prev) => ({
        ...prev,
        [key]: {
          ...(prev[key] ?? {}),
          [optionGroupKey]: valueUid,
        },
      }));
    },
    []
  );

  const handleOpen = useCallback((options?: { suppressEmptyError?: boolean }) => {
    hasPopupOpenedRef.current = true;
    setError(
      (options?.suppressEmptyError || rulesWithProducts.length)
        ? null
        : 'empty'
    );
    setExpandedPickKey(null);
    setOpen(true);
  }, [rulesWithProducts.length]);

  const handleClose = useCallback(() => {
    /** Leave hasPopupOpenedRef true so a routine checkout/updated right after a
     * manual dismiss doesn't reopen the picker; it resets when gifts become
     * unavailable (see the effect above) so a future opportunity can reopen it. */
    setOpen(false);
    setExpandedPickKey(null);
  }, []);
  handleOpenRef.current = handleOpen;
  handleCloseRef.current = handleClose;

  useEffect(() => {
    const openPopupWhenAvailable = (payload?: unknown) => {
      if (hasPopupOpenedRef.current) return;

      const checkoutCart = toCartModel(payload);
      const checkoutRaw = checkoutCart as CartModel & {
        has_available_free_gifts?: boolean;
      };
      const hasAvailableFreeGifts = Boolean(
        checkoutCart?.hasAvailableFreeGifts
        ?? checkoutRaw?.has_available_free_gifts
      );

      if (!hasAvailableFreeGifts) {
        hasPopupOpenedRef.current = false;
        return;
      }

      handleOpenRef.current?.({ suppressEmptyError: true });
    };

    const subscriptions = [
      events.on('checkout/initialized', openPopupWhenAvailable, { eager: true }),
      events.on('checkout/updated', openPopupWhenAvailable, { eager: true }),
    ];

    return () => {
      subscriptions.forEach((subscription) => subscription?.off());
    };
  }, []);

  useEffect(() => {
    if (!open) return;
    if (error === 'empty' && rulesWithProducts.length) {
      setError(null);
    }
  }, [open, error, rulesWithProducts.length]);

  const handleExpandConfigurableOrBundle = useCallback(
    (rule: AvailableFreeGiftRule, product: FreeGiftProduct) => {
      const pk = pickKey(rule.ruleId, product.sku);
      setError(null);
      setExpandedPickKey(pk);
      setConfigPicks((prev) => {
        if (prev[pk] && Object.keys(prev[pk]).length) return prev;
        const defaults = getDefaultOptionPicks(product);
        return Object.keys(defaults).length
          ? { ...prev, [pk]: defaults }
          : prev;
      });
    },
    []
  );

  const handleAddFreeGiftForRule = useCallback(
    async (rule: AvailableFreeGiftRule, product: FreeGiftProduct) => {
      if (!cart?.id) return;

      const pk = pickKey(rule.ruleId, product.sku);
      setSubmittingKey(pk);
      setError(null);
      try {
        const picks = configPicks[pk] ?? {};

        let selectedOptions: string[] | undefined;

        if (product.configurableOptions?.length) {
          selectedOptions = buildConfigurableUids(product, picks);
          if (
            selectedOptions.length !== product.configurableOptions.length
          ) {
            setError('configureRequired');
            return;
          }
        } else if (product.bundleItems?.length) {
          selectedOptions = buildBundleSelectedOptionUids(product, picks);
          const sorted = [...product.bundleItems].sort(
            (a, b) => bundleRowSortPosition(a) - bundleRowSortPosition(b)
          );
          const rowsWithChoices = sorted.filter((row) => row.values.length > 0);
          if (
            !selectedOptions.length ||
            selectedOptions.length !== rowsWithChoices.length
          ) {
            setError('configureRequired');
            return;
          }
        }

        await selectFreeGiftForCart({
          ruleId: rule.ruleId,
          sku: product.sku,
          quantity: rule.giftQty,
          ...(selectedOptions?.length ? { selectedOptions } : {}),
        });
        handleCloseRef.current?.();
      } catch (e: unknown) {
        const message = e instanceof Error ? e.message : String(e);
        setError(message || 'error');
      } finally {
        setSubmittingKey(null);
      }
    },
    [cart?.id, configPicks]
  );

  const hasPendingFreeGifts = Boolean(
    cart?.hasAvailableFreeGifts && cart?.availableFreeGifts?.length
  );
  const addedFreeGiftItems = cart?.items?.filter((item) => item.isFreeGift) ?? [];
  const hasAddedFreeGift = addedFreeGiftItems.length > 0;
  const addedFreeGiftNames = addedFreeGiftItems.map((item) => item.name).join(', ');

  /** Map internal keys to i18n; show GraphQL/network messages as-is (see Cart.FreeGiftSelection.error fallback). */
  const errorMessage =
    error === 'empty'
      ? dictionary.empty
      : error === 'configureRequired'
        ? dictionary.configureRequired
        : error === 'error'
          ? dictionary.error
          : error ?? null;

  /* Keep the inline error visible inside the scrolling modal body (esp. tall product lists). */
  useLayoutEffect(() => {
    if (!open || !errorMessage) return;
    errorAlertRef.current?.scrollIntoView({
      behavior: 'smooth',
      block: 'start',
      inline: 'nearest',
    });
  }, [open, errorMessage]);

  if (!open) {
    return (
      <div {...rest} data-testid="free-gift-selection-root">
        {!cart ? (
          <div className="cart-free-gift-selection__loading" aria-live="polite">
            <FreeGiftSelectionLoader />
          </div>
        ) : null}
        {cart && hasAddedFreeGift ? (
          <p className="cart-free-gift-selection__added-message" aria-live="polite">
            {dictionary.addedMessagePrefix.replace('{names}', addedFreeGiftNames)}
          </p>
        ) : null}
        {showTrigger && cart && hasPendingFreeGifts ? (
          <div className="cart-free-gift-selection__trigger">
            <p
              id={openTriggerHintId}
              className="cart-free-gift-selection__trigger-hint"
            >
              {dictionary.openTriggerHint}
            </p>
            <Button
              type="button"
              variant="secondary"
              data-testid="free-gift-selection-open"
              aria-describedby={openTriggerHintId}
              onClick={handleOpen}
            >
              {dictionary.openTrigger}
            </Button>
          </div>
        ) : null}
      </div>
    );
  }

  return (
    <Modal
      {...rest}
      data-testid="free-gift-selection-modal"
      aria-label={dictionary.ariaModal}
      className="cart-free-gift-selection__modal"
      size="medium"
      title={<h2>{dictionary.title}</h2>}
      centered
      onClose={handleClose}
    >
      {submittingKey ? <ProgressSpinner /> : null}

      {errorMessage ? (
        <div
          ref={errorAlertRef}
          className="cart-free-gift-selection__error-anchor"
          data-testid="free-gift-selection-error-alert"
        >
          <InLineAlert type="error" variant="primary" heading={errorMessage} />
        </div>
      ) : null}

      <div className="cart-free-gift-selection__rules">
        {rulesWithProducts.map((rule) => {
          const ruleHeadingId = `free-gift-rule-heading-${rule.ruleId}`;
          const ruleTitle =
            rule.ruleLabel && String(rule.ruleLabel).trim() !== ''
              ? String(rule.ruleLabel).trim()
              : `${dictionary.ruleLabelFallback} (#${rule.ruleId})`;
          return (
            <section key={rule.ruleId} className="cart-free-gift-selection__rule">
              <div className="cart-free-gift-selection__rule-header">
                <h3
                  id={ruleHeadingId}
                  className="cart-free-gift-selection__rule-title"
                >
                  {ruleTitle}
                </h3>
              </div>
              <ContentGrid
                emptyGridContent={<></>}
                maxColumns={3}
                columnWidth="minmax(220px, 1fr)"
                className="cart-free-gift-selection__grid"
                role="group"
                aria-labelledby={ruleHeadingId}
              >
                {rule.products.map((product) => {
                  const pk = pickKey(rule.ruleId, product.sku);
                  const needsOptionPicks = productNeedsOptionPicks(product);
                  const isExpanded = expandedPickKey === pk;
                  const isSubmittingThis = submittingKey === pk;
                  const addBusy = submittingKey !== null;

                  const imageNode = product.thumbnail?.url ? (
                    <Image
                      src={product.thumbnail.url}
                      alt={product.thumbnail.label ?? product.name}
                      width={200}
                      height={200}
                      loading="lazy"
                    />
                  ) : (
                    <div
                      className="cart-free-gift-selection__image-placeholder"
                      aria-hidden
                    />
                  );

                  const swatchesNode =
                    needsOptionPicks && isExpanded ? (
                      <div className="cart-free-gift-selection__config-wrap">
                        {product.configurableOptions?.map((co) => (
                          <select
                            key={co.uid ?? co.attributeUid}
                            className="cart-free-gift-selection__config-select"
                            aria-label={co.label}
                            value={configPicks[pk]?.[co.attributeUid] ?? ''}
                            onChange={(e) =>
                              setPick(
                                rule.ruleId,
                                product.sku,
                                co.attributeUid,
                                (e.target as HTMLSelectElement).value
                              )
                            }
                          >
                            <option value="">{dictionary.chooseOption}</option>
                            {co.values.map((v) => (
                              <option key={v.uid} value={v.uid}>
                                {v.label}
                              </option>
                            ))}
                          </select>
                        ))}
                        {product.bundleItems?.map((row) => (
                          <div
                            key={row.uid}
                            className="cart-free-gift-selection__bundle-slot"
                          >
                            {row.title ? (
                              <span className="cart-free-gift-selection__bundle-slot-title">
                                {row.title}
                              </span>
                            ) : null}
                            <select
                              className="cart-free-gift-selection__config-select"
                              aria-label={row.title || dictionary.chooseOption}
                              value={configPicks[pk]?.[row.uid] ?? ''}
                              onChange={(e) =>
                                setPick(
                                  rule.ruleId,
                                  product.sku,
                                  row.uid,
                                  (e.target as HTMLSelectElement).value
                                )
                              }
                            >
                              <option value="">{dictionary.chooseOption}</option>
                              {row.values.map((v) => (
                                <option key={v.uid} value={v.uid}>
                                  {v.label}
                                </option>
                              ))}
                            </select>
                          </div>
                        ))}
                      </div>
                    ) : undefined;

                  const actionNode = !needsOptionPicks ? (
                    <Button
                      type="button"
                      variant="primary"
                      disabled={addBusy}
                      aria-busy={isSubmittingThis}
                      data-testid={`free-gift-add-${rule.ruleId}-${product.sku}`}
                      onClick={() => void handleAddFreeGiftForRule(rule, product)}
                    >
                      {dictionary.addToCart}
                    </Button>
                  ) : !isExpanded ? (
                    <Button
                      type="button"
                      variant="secondary"
                      disabled={addBusy}
                      data-testid={`free-gift-expand-${rule.ruleId}-${product.sku}`}
                      onClick={() =>
                        handleExpandConfigurableOrBundle(rule, product)
                      }
                    >
                      {dictionary.selectProduct}
                    </Button>
                  ) : (
                    <Button
                      type="button"
                      variant="primary"
                      disabled={addBusy}
                      aria-busy={isSubmittingThis}
                      data-testid={`free-gift-add-${rule.ruleId}-${product.sku}`}
                      onClick={() => void handleAddFreeGiftForRule(rule, product)}
                    >
                      {dictionary.addToCart}
                    </Button>
                  );

                  return (
                    <div
                      key={product.sku}
                      className="cart-free-gift-selection__card-wrap"
                    >
                      <ProductItemCard
                        initialized
                        className={classes([
                          'cart-free-gift-selection__card',
                          [
                            'cart-free-gift-selection__card--selected',
                            needsOptionPicks && isExpanded,
                          ],
                        ])}
                        image={imageNode}
                        titleNode={<span>{product.name}</span>}
                        sku={<span>{product.sku}</span>}
                        swatches={swatchesNode}
                        actionButton={actionNode}
                      />
                    </div>
                  );
                })}
              </ContentGrid>
            </section>
          );
        })}
      </div>
    </Modal>
  );
};
